# Generated by Claude Opus 5.5 (claude.ai/code) · 2026-11-18
# Pester tests: time window, planning, window math, coverage.

BeforeAll {
    . (Join-Path $PSScriptRoot '../TestHelpers.ps1')
}

AfterAll {
    Remove-TestWork
}

Describe 'time window' {
    It 'handles a normal daytime window' {
        Test-WithinWindow -Open '09:00' -Close '17:00' -Now ([datetime]'2026-01-01 12:00') | Should -BeTrue
        Test-WithinWindow -Open '09:00' -Close '17:00' -Now ([datetime]'2026-01-01 18:00') | Should -BeFalse
    }
    It 'handles a window that wraps past midnight' {
        Test-WithinWindow -Open '23:00' -Close '06:00' -Now ([datetime]'2026-01-01 02:00') | Should -BeTrue
        Test-WithinWindow -Open '23:00' -Close '06:00' -Now ([datetime]'2026-01-01 23:30') | Should -BeTrue
        Test-WithinWindow -Open '23:00' -Close '06:00' -Now ([datetime]'2026-01-01 12:00') | Should -BeFalse
    }
}

Describe 'planning' {
    It 'puts mandatory first and preserves config order' {
        $cfg = @'
{ "window": { "open": "23:00", "close": "06:00" },
  "services": {
    "alpha": { "enabled": true,  "mandatory": false, "script": "x", "steps": [] },
    "beta":  { "enabled": true,  "mandatory": true,  "script": "x", "steps": [] },
    "gamma": { "enabled": false, "mandatory": false, "script": "x", "steps": [] },
    "delta": { "enabled": true,  "mandatory": false, "script": "x", "steps": [] }
  } }
'@ | ConvertFrom-Json
        $plan = Get-BackupPlan -Config $cfg
        @($plan.Service) | Should -Be @('beta', 'alpha', 'delta')
    }

    It 'scores the more overdue service first' {
        $ev = Join-Path $Work "plan-age-$([guid]::NewGuid().ToString('n').Substring(0,6)).jsonl"
        Add-Content -LiteralPath $ev -Value (@{ ts = '2026-11-01T00:00:00+00:00'; type = 'service.end'; svc = 'old'; status = 'ok'; bytes = 10 } | ConvertTo-Json -Compress)
        Add-Content -LiteralPath $ev -Value (@{ ts = '2026-11-06T00:00:00+00:00'; type = 'service.end'; svc = 'fresh'; status = 'ok'; bytes = 10 } | ConvertTo-Json -Compress)
        $proj = Get-ServiceProjection -EventsPath $ev
        $cfg = @'
{ "window": { "open": "23:00", "close": "06:00" },
  "services": { "old": { "enabled": true, "script": "x", "steps": [] }, "fresh": { "enabled": true, "script": "x", "steps": [] } } }
'@ | ConvertFrom-Json
        $plan = Get-BackupPlan -Config $cfg -Projection $proj -At ([datetime]'2026-11-06T12:00:00+00:00')
        @($plan.Service)[0] | Should -Be 'old'
    }

    It 'floats a never-run service above a recently backed-up one' {
        $ev = Join-Path $Work "plan-new-$([guid]::NewGuid().ToString('n').Substring(0,6)).jsonl"
        Add-Content -LiteralPath $ev -Value (@{ ts = '2026-11-06T00:00:00+00:00'; type = 'service.end'; svc = 'done'; status = 'ok'; bytes = 10 } | ConvertTo-Json -Compress)
        $proj = Get-ServiceProjection -EventsPath $ev
        $cfg = @'
{ "window": { "open": "23:00", "close": "06:00" },
  "services": { "done": { "enabled": true, "script": "x", "steps": [] }, "newbie": { "enabled": true, "script": "x", "steps": [] } } }
'@ | ConvertFrom-Json
        $plan = Get-BackupPlan -Config $cfg -Projection $proj -At ([datetime]'2026-11-06T12:00:00+00:00')
        @($plan.Service)[0] | Should -Be 'newbie'
    }

    It 'breaks never-run ties by size (biggest estimate first)' {
        $ev = Join-Path $Work "plan-size-$([guid]::NewGuid().ToString('n').Substring(0,6)).jsonl"
        Add-Content -LiteralPath $ev -Value (@{ ts = '2026-11-06T00:00:00+00:00'; type = 'step.end'; svc = 'big'; step = 'dump'; status = 'ok'; durationSec = 1000 } | ConvertTo-Json -Compress)
        Add-Content -LiteralPath $ev -Value (@{ ts = '2026-11-06T00:00:00+00:00'; type = 'step.end'; svc = 'small'; step = 'dump'; status = 'ok'; durationSec = 10 } | ConvertTo-Json -Compress)
        $proj = Get-ServiceProjection -EventsPath $ev   # both never *succeeded* -> never-run tie, est differs
        $cfg = @'
{ "window": { "open": "23:00", "close": "06:00" },
  "services": { "small": { "enabled": true, "script": "x", "steps": [] }, "big": { "enabled": true, "script": "x", "steps": [] } } }
'@ | ConvertFrom-Json
        $plan = Get-BackupPlan -Config $cfg -Projection $proj
        @($plan.Service)[0] | Should -Be 'big'
    }

    It 'forces mandatory to the front even against a higher score' {
        $ev = Join-Path $Work "plan-mand-$([guid]::NewGuid().ToString('n').Substring(0,6)).jsonl"
        # must: backed up recently (low score, but mandatory). other: very overdue (high score)
        Add-Content -LiteralPath $ev -Value (@{ ts = '2026-11-06T11:00:00+00:00'; type = 'service.end'; svc = 'must'; status = 'ok'; bytes = 10 } | ConvertTo-Json -Compress)
        Add-Content -LiteralPath $ev -Value (@{ ts = '2026-10-01T00:00:00+00:00'; type = 'service.end'; svc = 'other'; status = 'ok'; bytes = 10 } | ConvertTo-Json -Compress)
        $proj = Get-ServiceProjection -EventsPath $ev
        $cfg = @'
{ "window": { "open": "23:00", "close": "06:00" },
  "services": { "other": { "enabled": true, "mandatory": false, "script": "x", "steps": [] }, "must": { "enabled": true, "mandatory": true, "script": "x", "steps": [] } } }
'@ | ConvertFrom-Json
        $plan = Get-BackupPlan -Config $cfg -Projection $proj -At ([datetime]'2026-11-06T12:00:00+00:00')
        @($plan.Service)[0] | Should -Be 'must'
    }
}

Describe 'window math' {
    It 'computes window length across the midnight wrap' {
        (Get-WindowLengthSeconds -Open '23:00' -Close '06:00') | Should -Be 25200
        (Get-WindowLengthSeconds -Open '09:00' -Close '17:00') | Should -Be 28800
    }
    It 'computes seconds until the next close' {
        (Get-SecondsUntilClose -Close '06:00' -Now ([datetime]'2026-11-06T02:00:00')) | Should -Be 14400
        (Get-SecondsUntilClose -Close '06:00' -Now ([datetime]'2026-11-06T23:30:00')) | Should -Be 23400
    }
}

Describe 'coverage (archiver-computed overdue)' {
    It 'gfsy reports covered (<1) right after an archive, overdue (>=1) when stale' {
        $ev = Join-Path $Work "ov-$([guid]::NewGuid().ToString('n').Substring(0,6)).jsonl"
        Add-Content -LiteralPath $ev -Value (@{ ts = '2026-11-06T10:00:00+00:00'; type = 'service.archived'; svc = 'app'; tier = 'daily'; path = '/x' } | ConvertTo-Json -Compress)
        $cfg = @'
{ "window": { "open": "23:00", "close": "06:00" },
  "services": { "app": { "enabled": true, "script": "fixtures/mock-service.ps1",
    "syncArchive": { "script": "../src/recipes/archive-gfsy.ps1" }, "steps": [] } } }
'@ | ConvertFrom-Json
        # 2h after the archive -> covered
        (Get-ServiceOverdue -Config $cfg -Service 'app' -BaseDir $TestsDir -EventsPath $ev -At ([datetime]'2026-11-06T12:00:00+00:00')) | Should -BeLessThan 1
        # 2 days after -> due
        (Get-ServiceOverdue -Config $cfg -Service 'app' -BaseDir $TestsDir -EventsPath $ev -At ([datetime]'2026-11-08T12:00:00+00:00')) | Should -BeGreaterThan 1
    }

    It 'gfsy: a yearly within the daily period also covers the daily' {
        $ev = Join-Path $Work "ovy-$([guid]::NewGuid().ToString('n').Substring(0,6)).jsonl"
        Add-Content -LiteralPath $ev -Value (@{ ts = '2026-11-06T10:00:00+00:00'; type = 'service.archived'; svc = 'app'; tier = 'yearly'; path = '/x' } | ConvertTo-Json -Compress)
        $cfg = @'
{ "window": { "open": "23:00", "close": "06:00" },
  "services": { "app": { "enabled": true, "script": "fixtures/mock-service.ps1",
    "syncArchive": { "script": "../src/recipes/archive-gfsy.ps1" }, "steps": [] } } }
'@ | ConvertFrom-Json
        (Get-ServiceOverdue -Config $cfg -Service 'app' -BaseDir $TestsDir -EventsPath $ev -At ([datetime]'2026-11-06T13:00:00+00:00')) | Should -BeLessThan 1
    }

    It 'restic reports covered (<1) right after a snapshot, overdue (>=1) when stale' {
        $ev = Join-Path $Work "ovr-$([guid]::NewGuid().ToString('n').Substring(0,6)).jsonl"
        Add-Content -LiteralPath $ev -Value (@{ ts = '2026-11-06T10:00:00+00:00'; type = 'service.archived'; svc = 'app'; snapshot = 'abc'; repo = '/r' } | ConvertTo-Json -Compress)
        $cfg = @'
{ "window": { "open": "23:00", "close": "06:00" },
  "services": { "app": { "enabled": true, "script": "fixtures/mock-service.ps1",
    "syncArchive": { "script": "../src/recipes/archive-restic.ps1" }, "steps": [] } } }
'@ | ConvertFrom-Json
        (Get-ServiceOverdue -Config $cfg -Service 'app' -BaseDir $TestsDir -EventsPath $ev -At ([datetime]'2026-11-06T12:00:00+00:00')) | Should -BeLessThan 1
        (Get-ServiceOverdue -Config $cfg -Service 'app' -BaseDir $TestsDir -EventsPath $ev -At ([datetime]'2026-11-08T12:00:00+00:00')) | Should -BeGreaterThan 1
    }

    It 'returns null for a service with no archiver' {
        $ev = Join-Path $Work "ovn-$([guid]::NewGuid().ToString('n').Substring(0,6)).jsonl"
        $cfg = @'
{ "window": { "open": "23:00", "close": "06:00" },
  "services": { "app": { "enabled": true, "script": "fixtures/mock-service.ps1", "steps": [] } } }
'@ | ConvertFrom-Json
        (Get-ServiceOverdue -Config $cfg -Service 'app' -BaseDir $TestsDir -EventsPath $ev) | Should -BeNullOrEmpty
    }
}
